import { gainFor, useSoundSettings } from './settings';

/**
 * New-order alert sound (D-98, KAN-61): our own synthesized file (`/sounds/new-order.wav`, generated by
 * scripts/gen-alert-sound.mjs) played through Web Audio so the level applies, repeated until the order is
 * answered, plus vibration. Browsers only allow audio after a user gesture: `unlock()` must be called from
 * the «شروع شیفت» tap. Falls back to a synthesized beep if the file cannot load.
 */

/** Minimal Web Audio surface we use (real AudioContext in the app, a fake in tests). */
export interface AudioCtxLike {
  readonly state: string;
  readonly currentTime: number;
  readonly destination: unknown;
  resume(): Promise<void>;
  decodeAudioData(data: ArrayBuffer): Promise<AudioBufferLike>;
  createBufferSource(): {
    buffer: AudioBufferLike | null;
    connect(node: unknown): unknown;
    start(when?: number): void;
    stop(when?: number): void;
  };
  createGain(): { gain: { value: number }; connect(node: unknown): unknown };
  createOscillator(): {
    type: string;
    frequency: { value: number };
    connect(node: unknown): unknown;
    start(when?: number): void;
    stop(when?: number): void;
  };
}
export interface AudioBufferLike {
  readonly duration: number;
}

export interface SoundDeps {
  createContext: () => AudioCtxLike | null;
  fetchImpl: typeof fetch;
  vibrate: (pattern: number[]) => boolean;
  setTimer: (fn: () => void, ms: number) => unknown;
  clearTimer: (id: unknown) => void;
  url: string;
}

/** Pause between repeats (the sound itself is ~3.2 s). */
export const REPEAT_GAP_MS = 800;
const FALLBACK_SEC = 0.6;
export const VIBRATION = [400, 150, 400];

function browserDeps(): SoundDeps {
  const w = globalThis as unknown as {
    AudioContext?: new () => AudioCtxLike;
    webkitAudioContext?: new () => AudioCtxLike;
  };
  return {
    createContext: () => {
      const C = w.AudioContext ?? w.webkitAudioContext;
      return C ? new C() : null;
    },
    fetchImpl: (i, init) => globalThis.fetch(i, init),
    vibrate: (p) =>
      typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function'
        ? navigator.vibrate(p)
        : false,
    setTimer: (fn, ms) => setTimeout(fn, ms),
    clearTimer: (id) => clearTimeout(id as ReturnType<typeof setTimeout>),
    url: `${import.meta.env.BASE_URL}sounds/new-order.wav`,
  };
}

export function createSoundEngine(deps: SoundDeps = browserDeps()) {
  let ctx: AudioCtxLike | null = null;
  let buffer: AudioBufferLike | null = null;
  let loading: Promise<void> | null = null;
  let alerting = false;
  let muted = false;
  let timer: unknown = null;
  let stopCurrent: (() => void) | null = null;
  let gainNode: { gain: { value: number } } | null = null;

  const settings = () => useSoundSettings.getState();

  function load(): Promise<void> {
    const c = ctx;
    if (buffer || !c) return Promise.resolve();
    loading ??= (async () => {
      try {
        const res = await deps.fetchImpl(deps.url);
        if (res.ok) buffer = await c.decodeAudioData(await res.arrayBuffer());
      } catch {
        buffer = null; // fallback beep
      } finally {
        loading = null;
      }
    })();
    return loading;
  }

  function silence() {
    try {
      stopCurrent?.();
    } catch {
      /* already stopped */
    }
    stopCurrent = null;
  }

  /** Plays the alert once; returns its length in seconds. */
  function playOnce(): number {
    if (!ctx) return 0;
    silence();
    const gain = ctx.createGain();
    gain.gain.value = gainFor(settings().level);
    gain.connect(ctx.destination);
    gainNode = gain;
    if (buffer) {
      const src = ctx.createBufferSource();
      src.buffer = buffer;
      src.connect(gain);
      src.start();
      stopCurrent = () => src.stop();
      return buffer.duration;
    }
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = 880;
    osc.connect(gain);
    osc.start();
    osc.stop(ctx.currentTime + FALLBACK_SEC);
    stopCurrent = () => osc.stop();
    return FALLBACK_SEC;
  }

  function ring() {
    timer = null;
    if (!alerting) return;
    const sec = muted ? 0 : playOnce();
    if (settings().vibrate && !muted) deps.vibrate(VIBRATION);
    if (settings().repeat) timer = deps.setTimer(ring, Math.max(sec, FALLBACK_SEC) * 1000 + REPEAT_GAP_MS);
  }

  const engine = {
    /**
     * Call from a user tap. Creates/resumes the AudioContext synchronously (gesture rule), loads the
     * sound and plays it once as a test. Resolves true when sound can play.
     */
    async unlock({ test = true } = {}): Promise<boolean> {
      ctx ??= deps.createContext();
      if (!ctx) return false;
      try {
        if (ctx.state !== 'running') await ctx.resume();
      } catch {
        /* reported through state below */
      }
      await load();
      if (test) playOnce();
      return ctx.state === 'running';
    },
    get unlocked() {
      return !!ctx && ctx.state === 'running';
    },
    /** Settings preview (sound screen): one play; returns its length in ms (0 = no sound). */
    async preview(): Promise<number> {
      if (!(await engine.unlock({ test: false }))) return 0;
      return playOnce() * 1000;
    },
    stopPreview: silence,
    /** Start ringing for a new order (no-op while already ringing). */
    startAlert() {
      if (alerting) return;
      alerting = true;
      muted = false;
      ring();
    },
    /** «قطع صدا»: silence this alert; the order timer keeps running (screen specs). */
    mute() {
      muted = true;
      silence();
      deps.vibrate([0]);
    },
    /** The order was answered / expired: stop ringing. */
    stopAlert() {
      alerting = false;
      muted = false;
      if (timer !== null) deps.clearTimer(timer);
      timer = null;
      silence();
    },
    /** Live level change while something plays. */
    applyLevel() {
      if (gainNode) gainNode.gain.value = gainFor(settings().level);
    },
    get alerting() {
      return alerting;
    },
    get muted() {
      return muted;
    },
  };
  return engine;
}

export type SoundEngine = ReturnType<typeof createSoundEngine>;

let shared: SoundEngine | null = null;
/** The app-wide engine (one AudioContext per page). */
export const soundEngine = (): SoundEngine => (shared ??= createSoundEngine());
/** Tests: swap the engine. */
export const setSoundEngine = (e: SoundEngine | null) => {
  shared = e;
};
